    d = distance_to(enemy.x, enemy.y)
    r = hypot(me.x, me.y)
    if r > arena.radius - 1.8:
        re = hypot(enemy.x, enemy.y)
        if re > r - 0.5:
            b = bearing_to(0.0, 0.0)
            d = r
