def drive(me, enemy, arena):
    # Simple avoidance / approach logic.
    try:
        dist = distance_to(enemy.x, enemy.y)
        bearing = bearing_to(enemy.x, enemy.y)  # degrees, positive = left
    except Exception:
        return (0, 0)

    # Keep a safe distance from the spinner.
    safe_dist = 2.0  # meters
    if dist > safe_dist:
        # Move forward, steer a little toward the enemy.
        if bearing > 10:
            return (0.4, 1.0)   # turn left while advancing
        elif bearing < -10:
            return (1.0, 0.4)   # turn right while advancing
        else:
            return (1.0, 1.0)   # straight ahead
    # If we are too close, back off a bit.
    if dist < 0.8:
        return (-0.5, -0.5)     # reverse slowly
    # Otherwise stay still and let weapons act.
    return (0, 0)


