def drive(me, enemy, arena):
    try:
        dist = distance_to(enemy.x, enemy.y)
        bearing = bearing_to(enemy.x, enemy.y)  # degrees, positive = left
    except Exception:
        return (0, 0)

    safe_min = 1.5  # meters
    safe_max = 2.5  # meters

    # Too close: back away, turning opposite to bearing
    if dist < safe_min:
        if bearing > 0:
            return (-0.5, -0.2)   # turn right while backing
        else:
            return (-0.2, -0.5)   # turn left while backing

    # Within comfortable band: circle around enemy
    if safe_min <= dist <= safe_max:
        if bearing > 20:
            return (0.4, 1.0)     # veer left
        elif bearing < -20:
            return (1.0, 0.4)     # veer right
        else:
            return (0.7, 1.0)     # gentle left turn

    # Too far: approach while staying to side
    if bearing > 0:
        return (0.6, 1.0)         # steer left while advancing
    else:
        return (1.0, 0.6)         # steer right while advancing


